mat2 Rot(float a) {
    float s=sin(a), c=cos(a);
    return mat2(c, -s, s, c);
}

float sdBox(vec3 p, vec3 s) {
    p = abs(p)-s;
	return length(max(p, 0.))+min(max(p.x, max(p.y, p.z)), 0.);
}

float GetDist(vec3 p) {
    vec2 uv = p.xz;

    uv *= Rot(0.18 * p.y + 0.18 * cos(1.5 * iTime + 2. * p.y + 0.2 * dot(uv, uv)));
    uv = abs(uv) - 1.6;

    float time = iTime + 2. * p.y;
    float sc = 2.; //length(uv) * 32.;

    float r = 0.05;
    //r += 0.05 * cos(4. * length(uv));
    float sp = 1.;
    float n = 7.;
    float d = 100.;
    for (float i = 0.; i < n; i++) {
        float e = (i/n) * pi;
        vec2 p = 0.5 * cos(time + e + 0.25 * pi * cos(iTime + 2. * e)) * vec2(cos(e), sin(e));
        d = smin(d, length(uv - p) - 0.1 - 0.05 * cos(iTime + 10. * p.y + e));
    }

    return 0.7 * d;
}

float RayMarch(vec3 ro, vec3 rd) {
	float dO=0.;

    for(int i=0; i<MAX_STEPS; i++) {
    	vec3 p = ro + rd*dO;
        float dS = GetDist(p);
        dO += dS;
        if(dO>MAX_DIST || abs(dS)<SURF_DIST) break;
    }

    return dO;
}

vec3 GetNormal(vec3 p) {
	float d = GetDist(p);
    vec2 e = vec2(.001, 0);

    vec3 n = d - vec3(
        GetDist(p-e.xyy),
        GetDist(p-e.yxy),
        GetDist(p-e.yyx));

    return normalize(n);
}

vec3 GetRayDir(vec2 uv, vec3 p, vec3 l, float z) {
    vec3 f = normalize(l-p),
        r = normalize(cross(vec3(0,1,0), f)),
        u = cross(f,r),
        c = f*z,
        i = c + uv.x*r + uv.y*u,
        d = normalize(i);
    return d;
}

float GetLight(vec3 p, vec3 lightPos) {
   // vec3 lightPos = vec3(0, 5, 6);
