    vec3 n = GetNormal(p);

    float dif = clamp(dot(n, l), 0., 1.);
    float d = RayMarch(p+n*SURF_DIST*2., l);
    dif = 0.2 + 0.8 * dif * step(length(lightPos-p), d);
   // if(d<length(lightPos-p)) dif = 0.;

    return dif;
}

